}

def earliest_meeting(arrival, info):
    """Return (start, end) of earliest feasible meeting given arrival time, or None."""
    start = max(arrival, info['window_start'])
    end = start + info['duration']
    if end <= info['window_end']:
        return start, end
    return None

def build_schedule(order):
    """Try to build a schedule following the given order of friends."""
    steps = []
    cur_loc = start_location
    cur_time = start_time
    steps.append(f"You start at {cur_loc} at {from_minutes(cur_time)}.")
    for name in order:
        info = friends[name]
        # travel to friend's location
        travel_time = travel.get((cur_loc, info['location']))
        if travel_time is None:
            return None  # impossible path
        cur_time += travel_time
        steps.append(f"You travel to {info['location']} in {travel_time} minutes and arrive at {from_minutes(cur_time)}.")
        # possibly wait and meet
        meeting = earliest_meeting(cur_time, info)
        if meeting is None:
            return None
        meet_start, meet_end = meeting
        if meet_start > cur_time:
            steps.append(f"You wait until {from_minutes(meet_start)}.")
        steps.append(f"You meet {name} from {from_minutes(meet_start)} to {from_minutes(meet_end)}.")
        cur_time = meet_end
        cur_loc = info['location']
    return steps

best = []
best_len = -1
for r in range(1, len(friends)+1):
    for order in permutations(friends.keys(), r):
        sched = build_schedule(order)
        if sched:
            if len(order) > best_len:
                best_len = len(order)
                best = sched
            # Tie‑breaker: earlier finish time
            elif len(order) == best_len:
                # compare final time
                def final_time(s):
                    # last element with a time is either a wait or a meet; extract its time
                    for txt in reversed(s):
                        if "at " in txt:
                            return to_minutes(txt.split(" at ")[1].replace(".", ""))
                        if "until " in txt:
                            return to_minutes(txt.split(" until ")[1].replace(".", ""))
                        if "from " in txt:
                            parts = txt.split(" from ")[1]
                            end = parts.split(" to ")[1]
                            return to_minutes(end)
                    return 0
                if final_time(sched) < final_time(best):
                    best = sched

